"""Deleted generated bytes cannot be downloaded, staged or sent using old approvals."""
import pytest
from fastapi.testclient import TestClient

from office import artifact_library as library
from office.api import create_app
from office.store import WorkflowError
from test_youtube_delivery import released_fixture


@pytest.fixture
def current_video(tmp_path):
    store, job_id = released_fixture(tmp_path)
    job = store.job(job_id)
    manifest = job['manifest']
    for index, record in enumerate(manifest['files']):
        record['id'] = f'asset_current_{index}'
    store.update_job(job_id, manifest=manifest)
    create_app(store)
    return store, job_id, manifest['files'][0]


def put_in_trash(store, record):
    # Arrange the existing logical-trash format independently of eligibility policy.
    with store.connection() as db:
        groups, _ = library._scan(store, db)
    item = next(item for item in groups.values() if any(file['path'] == record['path'] for file in item['files']))
    entry = {'state': 'trash', 'paths': [file['path'] for file in item['files']],
             'files': item['files'], 'summary': library._public(item)}
    store.set_setting(library.KEY, {'entries': {item['id']: entry}, 'receipts': {}})
    return item['id']


@pytest.mark.parametrize('endpoint', ['package', 'review-package', 'artifact', 'blog-preview'])
def test_current_trash_cannot_be_downloaded_through_existing_approvals(current_video, endpoint):
    store, job_id, record = current_video
    if endpoint == 'blog-preview':
        manifest = store.job(job_id)['manifest']
        record = next(file for file in manifest['files'] if file['name'] == 'blog.md')
        record['name'] = 'tistory.md'
        store.update_job(job_id, manifest=manifest)
    before = store.job(job_id)
    client = TestClient(create_app(store), base_url='http://localhost:8510')
    routes = {'package': f'/api/jobs/{job_id}/package',
              'review-package': f'/api/jobs/{job_id}/review-package',
              'artifact': f'/api/artifacts/{record["id"]}',
              'blog-preview': f'/api/jobs/{job_id}/blog-preview?format=markdown'}
    assert client.get(routes[endpoint]).status_code == 200
    put_in_trash(store, record)
    response = client.get(routes[endpoint])
    assert response.status_code == 409
    assert (store.artifacts / record['path']).is_file()
    assert store.job(job_id) == before


@pytest.mark.parametrize('consumer', ['staging', 'youtube', 'owner', 'newsletter'])
def test_current_trash_is_rejected_before_staging_or_upload(current_video, consumer):
    from office.staging import _verified_records
    from office.youtube_delivery import _released_video
    from office.owner_drafts import _file
    from office.newsletter import _released_job

    store, job_id, record = current_video
    before = store.job(job_id)
    def newsletter_check():
        with store.connection() as db:
            return _released_job(db, store, job_id)
    checks = {'staging': lambda: _verified_records(store, store.job(job_id)),
              'youtube': lambda: _released_video(store, job_id),
              'owner': lambda: _file(store, record),
              'newsletter': newsletter_check}
    checks[consumer]()
    item_id = put_in_trash(store, record)
    with pytest.raises(WorkflowError, match='휴지통|삭제'):
        checks[consumer]()
    token = library.quote(store, [item_id], 'restore')['token']
    library.change(store, [item_id], 'restore', token, 'restore-consumer-fixture')
    checks[consumer]()
    assert store.job(job_id) == before
    assert store.setting('deliveries', {}) == {}
